package local.aicenter.core;
/** Synthetic independent golden values cross-checked with SciPy 1.17.0. */
public final class MeasurementSystemTest {
 private static int checks;
 private static void near(double actual,double expected){checks++;if(Math.abs(actual-expected)>1e-9*Math.max(1,Math.abs(expected)))throw new AssertionError(actual+" != "+expected);}
 private static void yes(boolean condition){checks++;if(!condition)throw new AssertionError();}
 private static void rejects(Runnable action){checks++;try{action.run();throw new AssertionError("accepted invalid design");}catch(IllegalArgumentException expected){}}
 public static String fixture(){StringBuilder b=new StringBuilder();for(int p=1;p<=3;p++)for(int o=0;o<2;o++)for(int r=1;r<=2;r++)b.append("P").append(p).append(',').append(o==0?"A":"B").append(',').append(r).append(',').append(10*p+2*o+(r==1?-1:1)).append('\n');return b.toString();}
 public static void main(String[] args){String input=fixture();MeasurementSystem.Grr full=MeasurementSystem.crossed(input,true,false,100);near(full.ssPart,800);near(full.ssOperator,12);near(full.ssInteraction,0);near(full.ssError,12);near(full.repeatability,2);near(full.operator,2);near(full.part,100);near(full.grr,4);near(full.total,104);near(full.studyVariation(full.grr),19.6116135138184);near(full.contribution(full.grr),3.846153846153846);near(full.interactionP,1);yes(!full.pooled);near(full.ndc,7);
 MeasurementSystem.Grr pooled=MeasurementSystem.crossed(input,true,true,100);yes(pooled.pooled);near(pooled.repeatability,1.5);near(pooled.operator,1.75);near(pooled.part,99.625);near(pooled.grr,3.25);near(pooled.total,102.875);near(pooled.tolerancePercent,10.816653826391967);near(pooled.studyVariation(pooled.grr),17.77406468581821);near(pooled.contribution(pooled.grr),3.1591737545565004);
 rejects(()->MeasurementSystem.crossed(input,false,true,100));rejects(()->MeasurementSystem.crossed(input+"P1,A,1,9",true,true,100));rejects(()->MeasurementSystem.crossed(input.replace("P1,A,1,9\n",""),true,true,100));rejects(()->MeasurementSystem.crossed(input.replace("P1,A,1,9","P1,A,0,9"),true,true,100));rejects(()->MeasurementSystem.crossed(input,true,true,-1));rejects(()->MeasurementSystem.crossed(input,true,true,Double.NaN));
 String interactionInput=input.replace("P2,B,1,21","P2,B,1,23").replace("P2,B,2,23","P2,B,2,25").replace("P3,B,1,31","P3,B,1,37").replace("P3,B,2,33","P3,B,2,39");MeasurementSystem.Grr withInteraction=MeasurementSystem.crossed(interactionInput,true,false,0);near(withInteraction.interactionP,.05991616668036493);near(withInteraction.operator,9.333333333333341);near(withInteraction.interaction,3.666666666666666);near(withInteraction.part,130);yes(Double.isNaN(withInteraction.tolerancePercent));
 MeasurementSystem.Bias bias=MeasurementSystem.bias("9\n10\n11\n12\n13",10,true);near(bias.bias,1);near(bias.sd,Math.sqrt(2.5));near(bias.se,.7071067811865476);near(bias.t,1.414213562373095);near(bias.p,.2301996410804989);near(bias.lower,-.9632431614775572);near(bias.upper,2.963243161477557);yes(Double.isNaN(MeasurementSystem.bias("10\n10",10,true).p));rejects(()->MeasurementSystem.bias("10",10,true));rejects(()->MeasurementSystem.bias("10\nNaN",10,true));rejects(()->MeasurementSystem.bias("10\n11",10,false));
 MeasurementSystem.Linearity linear=MeasurementSystem.linearity("10,10\n10,11\n20,21\n20,23\n30,32\n30,35",true);near(linear.slope,.15);near(linear.intercept,-1);near(linear.slopeSe,.06614378277661476);near(linear.p,.0859375);yes(linear.lower<0&&linear.upper>0);rejects(()->MeasurementSystem.linearity("10,10\n10,11\n20,21\n20,23\n20,32\n20,35",true));rejects(()->MeasurementSystem.linearity("10,10\n10,11\n20,21\n20,23\n30,32\n40,35",true));rejects(()->MeasurementSystem.linearity("10,10\n10,11\n20,21\n20,23\n30,32\n30,35",false));
 System.out.println("PASS measurement system: "+checks+" assertions (synthetic host; not full MSA acceptance)");}
}
